        ('mm-04-mf-1187', 4, '178 + 95 + 62', '335', 3),
        ('mm-04-mf-1188', 4, '105 × 4', '420', 3),
        ('mm-04-mf-1189', 4, '630 ÷ 2', '315', 3),
        ('mm-04-mf-1190', 4, '(13 + 11) × 9', '216', 3),
        ('mm-04-mf-1191', 4, '168 + 294 + 96', '558', 3),
        ('mm-04-mf-1192', 4, '22 × 12', '264', 3),
        ('mm-04-mf-1193', 4, '? × 4 = 1140', '285', 3),
        ('mm-04-mf-1194', 4, '27 × 25', '675', 3),
        ('mm-04-mf-1195', 4, '199 + 375', '574', 3),
        ('mm-04-mf-1196', 4, '816 - 499', '317', 3),
