    ) AS v (question_code, chapter_no, left_text, right_text, difficulty)
) AS s
ON t.question_code = s.question_code
WHEN MATCHED AND (t.subject, t.chapter_no, t.left_text, t.right_text, t.difficulty) IS DISTINCT FROM (s.subject, s.chapter_no, s.left_text, s.right_text, s.difficulty) THEN
    UPDATE SET subject = s.subject, chapter_no = s.chapter_no, left_text = s.left_text, right_text = s.right_text, difficulty = s.difficulty
WHEN NOT MATCHED THEN
    INSERT (question_code, subject, chapter_no, left_text, right_text, difficulty) VALUES (s.question_code, s.subject, s.chapter_no, s.left_text, s.right_text, s.difficulty)
WHEN NOT MATCHED BY SOURCE AND t.subject = 'mental_maths' THEN
    DELETE;
